-- Canonical schema for new local test databases; existing Cloudflare D1 is preserved.
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',price_cents INTEGER NOT NULL CHECK(price_cents>0),currency TEXT NOT NULL DEFAULT 'USD',active INTEGER NOT NULL DEFAULT 1,deleted_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),key_ciphertext TEXT NOT NULL,key_fingerprint TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'available' CHECK(status IN ('available','sold')),order_item_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,status TEXT NOT NULL DEFAULT 'pending',currency TEXT NOT NULL DEFAULT 'USD',total_cents INTEGER NOT NULL CHECK(total_cents>0),access_token_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),product_id TEXT NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),unit_price_cents INTEGER NOT NULL,subtotal_cents INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS payments(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),provider TEXT NOT NULL,provider_payment_id TEXT UNIQUE,amount_cents INTEGER NOT NULL,currency TEXT NOT NULL,status TEXT NOT NULL,evidence_json TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS deliveries(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),order_item_id TEXT NOT NULL REFERENCES order_items(id),inventory_id TEXT NOT NULL UNIQUE REFERENCES inventory(id),payment_id TEXT NOT NULL REFERENCES payments(id),delivered_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS product_payment_plans(product_id TEXT PRIMARY KEY REFERENCES products(id),plan_id TEXT NOT NULL,credits_per_purchase INTEGER NOT NULL CHECK(credits_per_purchase>0),enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS payment_attempts(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),product_id TEXT NOT NULL REFERENCES products(id),plan_id TEXT NOT NULL,request_id TEXT NOT NULL UNIQUE,status TEXT NOT NULL CHECK(status IN ('created','verifying','settling','settled','uncertain','failed')),receipt_json TEXT,error_code TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY AUTOINCREMENT,action TEXT NOT NULL,entity_id TEXT,detail TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
